const SUPABASE_URL = 'https://vinwnykuumifpctdjxbu.supabase.co';
const SUPABASE_KEY = $env.SUPABASE_SERVICE_ROLE_KEY; // set in n8n env/credentials — never hardcode

const headers = { apikey: SUPABASE_KEY };

// 1. Fetch all active tracked areas
const areas = await this.helpers.httpRequest({
  method: 'GET',
  url: SUPABASE_URL + '/rest/v1/tracked_areas',
  headers,
  qs: {
    select: 'council_slug'
  }
});

// 2. Deduplicate council slugs
const seen = new Set();
const slugs = [];
for (const area of areas) {
  if (area.council_slug && !seen.has(area.council_slug)) {
    seen.add(area.council_slug);
    slugs.push(area.council_slug);
  }
}
if (slugs.length === 0) return [];

// 3. Fetch council details for all slugs in one query
const councils = await this.helpers.httpRequest({
  method: 'GET',
  url: SUPABASE_URL + '/rest/v1/councils',
  headers,
  qs: {
    slug: 'in.(' + slugs.join(',') + ')',
    select: 'slug,name,portal_url,portal_type',
    supported: 'eq.true'
  }
});
if (councils.length === 0) return [];

// 4. Calculate date range — last 7 days in DD/MM/YYYY
const now = new Date();
const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
function fmt(d) {
  const dd = String(d.getDate()).padStart(2, '0');
  const mm = String(d.getMonth() + 1).padStart(2, '0');
  return dd + '/' + mm + '/' + d.getFullYear();
}
const dateFrom = fmt(weekAgo);
const dateTo = fmt(now);

// 5. Return one item per supported council
return councils.map(function(c) {
  return {
    json: {
      council_slug: c.slug,
      council_name: c.name,
      portal_url:   c.portal_url,
      portal_type:  c.portal_type || 'idox_search_do',
      date_from:    dateFrom,
      date_to:      dateTo
    }
  };
});

const html    = $input.first().json.data;
const context = $input.first().json;

if (!html || typeof html !== 'string') {
  return [{ json: { applications: [], council_slug: $('Fetch Areas & Build Council List').itemMatching(0).json.council_slug, parse_error: 'No HTML received' } }];
}

function stripTags(h) {
  return h
    .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&nbsp;/g, ' ')
    .replace(/&#(\d+);/g, function(_, n) { return String.fromCharCode(Number(n)); })
    .replace(/<[^>]+>/g, '');
}

function parseAddress(cellHtml) {
  return stripTags(cellHtml)
    .split(/[\n,]+/)
    .map(function(s) { return s.trim(); })
    .filter(function(s) { return s.length > 0; })
    .join(', ');
}

function parseDate(cellHtml) {
  const text = stripTags(cellHtml).trim();
  const m = text.match(/(\d{2})\/(\d{2})\/(\d{4})/);
  return m ? (m[3] + '-' + m[2] + '-' + m[1]) : null;
}

if (/your query did not return any results/i.test(html)) {
  return [{ json: { applications: [], council_slug: $('Fetch Areas & Build Council List').itemMatching(0).json.council_slug, scraped_count: 0 } }];
}

const tableStart = html.indexOf('<th><strong>Application number');
if (tableStart === -1) {
  return [{ json: { applications: [], council_slug: $('Fetch Areas & Build Council List').itemMatching(0).json.council_slug, parse_error: 'Results table not found' } }];
}

const tableOpenPos = html.lastIndexOf('<table', tableStart);
const tableEndPos  = html.indexOf('</table>', tableStart);
if (tableOpenPos === -1 || tableEndPos === -1) {
  return [{ json: { applications: [], council_slug: $('Fetch Areas & Build Council List').itemMatching(0).json.council_slug, parse_error: 'Table boundaries not found' } }];
}

const tableHtml  = html.slice(tableOpenPos, tableEndPos + 8);
const rowChunks  = tableHtml.split(/<tr[^>]*>/i).slice(1);
const applications = [];

for (var i = 0; i < rowChunks.length; i++) {
  const chunk = rowChunks[i];
  if (/<th/i.test(chunk) || chunk.indexOf('PKID=') === -1) continue;
  const cellChunks = chunk.split(/<td[^>]*>/i).slice(1);
  if (cellChunks.length < 6) continue;
  const cells    = cellChunks.map(function(c) { return c.replace(/<\/td>[\s\S]*/i, ''); });
  const refMatch = /<a[^>]+href="([^"]*PKID=[^"]*)"[^>]*>([^<]+)<\/a>/i.exec(cells[0]);
  if (!refMatch) continue;
  applications.push({
    reference:        refMatch[2].trim(),
    address:          parseAddress(cells[3]),
    description:      stripTags(cells[4]).trim(),
    status:           stripTags(cells[5]).trim(),
    application_date: parseDate(cells[1]),
    decision_date:    cells[6] ? parseDate(cells[6]) : null
  });
}

return [{ json: { council_slug: $('Fetch Areas & Build Council List').itemMatching(0).json.council_slug, applications: applications, scraped_count: applications.length } }];

// Forward EVERY council that has applications — not just the first item.
// (The Idox node outputs all councils in one batch; the old $input.first()
// silently dropped every council after the first.)
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  if (j.applications && j.applications.length > 0) {
    out.push({ json: { council_slug: j.council_slug, applications: j.applications } });
  }
}
return out;

// ===== Idox Scrape (GET + cookie pagination) =====
// Replaces the broken POST path. Works for BOTH Idox skins:
//   - newer: <li class="searchresult">  (e.g. Westminster)
//   - older: <tr class="odd|even">
// ScraperAPI premium GB proxy + sticky session_number + JSESSIONID cookie,
// so Idox pagination (pagedSearchResults.do) survives across proxied requests.

const SCRAPER_KEY = $env.SCRAPERAPI_KEY;
const httpRequest = (opts) => this.helpers.httpRequest(opts);

// Shared hard deadline (set below). No request starts after it, so the node
// always returns before n8n's 300s kill — worst overshoot is one in-flight request.
let DEADLINE = Infinity;

function proxied(target, session) {
  return 'http://api.scraperapi.com'
    + '?api_key=' + SCRAPER_KEY
    + '&premium=true&country_code=gb'
    + '&session_number=' + session
    + '&keep_headers=true'
    + '&url=' + encodeURIComponent(target);
}

function cookieFrom(headers) {
  let sc = headers && (headers['set-cookie'] || headers['Set-Cookie']);
  if (!sc) return '';
  if (!Array.isArray(sc)) sc = [sc];
  return sc.map((c) => String(c).split(';')[0]).filter((c) => /JSESSIONID/i.test(c)).join('; ');
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function getPage(target, cookie, session) {
  if (Date.now() > DEADLINE) throw new Error('time budget reached — skipping remaining requests');
  const headers = {};
  if (cookie) headers['Cookie'] = cookie;
  // ScraperAPI returns the odd transient 500 — retry the SAME session (keeps the Idox cookie valid)
  let lastErr;
  for (let attempt = 0; attempt < 2; attempt++) {
    try {
      const res = await httpRequest({
        method: 'GET',
        url: proxied(target, session),
        headers,
        returnFullResponse: true,
        timeout: 30000,
      });
      const code = res.statusCode || 200;
      const body = typeof res.body === 'string' ? res.body : String(res.body || '');
      if (code >= 500) throw new Error('ScraperAPI status ' + code + ' :: ' + body.slice(0, 200));
      return { body, cookie: cookieFrom(res.headers) };
    } catch (e) {
      // capture the underlying ScraperAPI response body if n8n attached it
      const detail = (e && (e.message || '')) + ' :: ' + (e && e.response && (typeof e.response.body === 'string' ? e.response.body.slice(0, 200) : JSON.stringify(e.response.body || {}).slice(0, 200)) || '');
      lastErr = new Error(detail);
      await sleep(1500 * (attempt + 1));
    }
  }
  throw lastErr;
}

function stripTags(s) {
  return String(s).replace(/<[^>]+>/g, ' ').replace(/&amp;/g, '&').replace(/&#39;/g, "'")
    .replace(/&quot;/g, '"').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim();
}

const MONTHS = { Jan:'01',Feb:'02',Mar:'03',Apr:'04',May:'05',Jun:'06',Jul:'07',Aug:'08',Sep:'09',Oct:'10',Nov:'11',Dec:'12' };
function parseTextDate(raw) {
  // "Tue 30 Jun 2026" or "30 Jun 2026"
  const m = String(raw).match(/(\d{1,2})\s+([A-Za-z]{3})\s+(\d{4})/);
  if (!m) return null;
  return m[3] + '-' + (MONTHS[m[2]] || '01') + '-' + String(m[1]).padStart(2, '0');
}
function parseSlashDate(raw) {
  const m = String(raw).match(/(\d{2})\/(\d{2})\/(\d{4})/);
  return m ? m[3] + '-' + m[2] + '-' + m[1] : null;
}

// ---- newer skin: <li class="searchresult"> ----
function parseLiFormat(html) {
  const out = [];
  const items = html.split('<li class="searchresult">').slice(1);
  for (const chunk of items) {
    const block = chunk.split('</li>')[0];
    const refM = block.match(/Ref\.\s*No:\s*([0-9A-Za-z\/]+)/);
    if (!refM) continue;
    const descM = block.match(/class="summaryLink"[^>]*>\s*<div[^>]*>([\s\S]*?)<\/div>/i)
      || block.match(/class="summaryLink"[^>]*>([\s\S]*?)<\/a>/i);
    const addrM = block.match(/<p class="address">([\s\S]*?)<\/p>/i);
    // status: newer skin uses a coloured badge, others put "Status: X" in the metaInfo line
    const statM = block.match(/badge-status[\s\S]*?class="value">([^<]+)</i)
      || block.match(/Status:\s*([^<|]+?)\s*(?:<|\||$)/i);
    // received/validated date label varies by Idox install (Received / Validated / Registered)
    const recM = block.match(/(?:Received|Validated|Registered):\s*([A-Za-z]{0,3}\s*\d{1,2}\s+[A-Za-z]{3}\s+\d{4})/i);
    const keyM = block.match(/applicationDetails\.do\?keyVal=([^&"]+)/);
    out.push({
      reference: refM[1].trim(),
      address: addrM ? stripTags(addrM[1]) : null,
      description: descM ? stripTags(descM[1]) : null,
      status: statM ? statM[1].trim() : null,
      application_date: recM ? parseTextDate(recM[1]) : null,
      decision_date: null,
      key_val: keyM ? keyM[1] : null,
    });
  }
  return out;
}

// ---- older skin: <tr class="odd|even"> ----
function parseTrFormat(html) {
  const out = [];
  const rowRegex = /<tr[^>]+class=["'](?:odd|even)["'][^>]*>([\s\S]*?)<\/tr>/gi;
  let m;
  while ((m = rowRegex.exec(html)) !== null) {
    const row = m[1];
    const refMatch = /<td[^>]*class=["'][^"']*number[^"']*["'][^>]*>[\s\S]*?<a[^>]*href=["']([^"']*)["'][^>]*>\s*([^<]+)\s*<\/a>/i.exec(row);
    if (!refMatch) continue;
    const addrMatch = /<td[^>]*class=["'][^"']*address[^"']*["'][^>]*>([\s\S]*?)<\/td>/i.exec(row);
    const descMatch = /<td[^>]*class=["'][^"']*description[^"']*["'][^>]*>([\s\S]*?)<\/td>/i.exec(row);
    const statMatch = /<td[^>]*class=["'][^"']*status[^"']*["'][^>]*>([\s\S]*?)<\/td>/i.exec(row);
    const dateMatch = /<td[^>]*class=["'][^"']*date[^"']*["'][^>]*>([\s\S]*?)<\/td>/i.exec(row);
    const keyM = /keyVal=([^&"']+)/.exec(refMatch[1]);
    out.push({
      reference: refMatch[2].trim(),
      address: addrMatch ? stripTags(addrMatch[1]) : null,
      description: descMatch ? stripTags(descMatch[1]) : null,
      status: statMatch ? stripTags(statMatch[1]) : null,
      application_date: dateMatch ? parseSlashDate(dateMatch[1]) : null,
      decision_date: null,
      key_val: keyM ? keyM[1] : null,
    });
  }
  return out;
}

// ---- single-result redirect: Idox jumps straight to applicationDetails.do when a
// search matches exactly one record, so there is no results list to parse ----
function parseDetailsPage(html) {
  if (html.indexOf('simpleDetailsTable') === -1) return [];
  const tbl = (html.match(/<table[^>]*id="simpleDetailsTable"[\s\S]*?<\/table>/i) || [])[0] || '';
  const map = {};
  for (const m of tbl.matchAll(/<th[^>]*>([\s\S]*?)<\/th>\s*<td[^>]*>([\s\S]*?)<\/td>/gi)) {
    map[stripTags(m[1]).toLowerCase()] = stripTags(m[2]);
  }
  if (!map['reference']) return [];
  const keyM = html.match(/keyVal=([A-Z0-9]+)/i);
  return [{
    reference: map['reference'],
    address: map['address'] || null,
    description: map['proposal'] || null,
    status: map['status'] || null,
    application_date: map['application received'] ? parseTextDate(map['application received']) : null,
    decision_date: map['decision issued date'] ? parseTextDate(map['decision issued date']) : null,
    key_val: keyM ? keyM[1] : null,
  }];
}

function parseAny(html) {
  if (html.indexOf('<li class="searchresult">') !== -1) return parseLiFormat(html);
  const tr = parseTrFormat(html);
  if (tr.length > 0) return tr;
  return parseDetailsPage(html);
}
function totalReported(html) {
  const m = html.match(/of\s+<[^>]*>?\s*(\d+)/i) || html.match(/of\s+(\d+)\s*(?:results|<)/i) || html.match(/Showing[\s\S]{0,80}?of\s+(\d+)/i);
  return m ? parseInt(m[1], 10) : 0;
}

async function scrapeCouncil(ctx, deadline) {
  // normalise: drop trailing slash, and a trailing /search.do that some councils store (e.g. haringey)
  const portal = String(ctx.portal_url || '').replace(/\/+$/, '').replace(/\/search\.do$/i, '');
  const slug = ctx.council_slug;
  const session = Math.floor(Math.random() * 100000);

  // 1) advanced page -> _csrf + session cookie
  const adv = await getPage(portal + '/search.do?action=advanced&searchType=Application', '', session);
  const csrf = (adv.body.match(/name="_csrf"\s+value="([^"]+)"/) || adv.body.match(/<input[^>]+name=["']_csrf["'][^>]+value=["']([^"']+)["']/i) || [])[1] || '';
  const cookie = adv.cookie;

  // Not an Idox search.do portal (e.g. Northgate / planning-register) -> skip fast, don't retry-storm
  if (!csrf) {
    return { council_slug: slug, applications: [], scraped_count: 0, node_version: 'v5-budget', skipped: 'no _csrf — not an Idox search.do portal' };
  }

  // 2) first page of results (keep cookie + same proxy session)
  const searchUrl = portal + '/advancedSearchResults.do?action=firstPage'
    + '&searchType=Application&caseAddressType=Application'
    + '&date(applicationReceivedStart)=' + ctx.date_from
    + '&date(applicationReceivedEnd)=' + ctx.date_to
    + '&searchCriteria.resultsPerPage=100&_csrf=' + encodeURIComponent(csrf);
  const first = await getPage(searchUrl, cookie, session);

  const byRef = new Map();
  for (const a of parseAny(first.body)) byRef.set(a.reference, a);
  const tot = totalReported(first.body);

  // 3) paginate via pagedSearchResults.do (cookie keeps the Idox search alive)
  // Sequential on purpose: parallel requests share one Idox session and intermittently
  // drop a page. Speed is fine because non-Idox councils are filtered out upstream.
  const sessCookie = first.cookie || cookie;
  const lastPage = Math.min(Math.ceil((tot || byRef.size) / 10), 50);
  for (let p = 2; p <= lastPage; p++) {
    if (deadline && Date.now() > deadline) break; // out of time budget — return what we have so far
    const pageUrl = portal + '/pagedSearchResults.do?action=page&searchCriteria.page=' + p + '&_csrf=' + encodeURIComponent(csrf);
    let rows = [];
    // retry transient empty/expired pages before giving up on this page
    for (let attempt = 0; attempt < 3 && rows.length === 0; attempt++) {
      const pg = await getPage(pageUrl, sessCookie, session);
      rows = parseAny(pg.body);
    }
    for (const a of rows) byRef.set(a.reference, a);
  }

  return {
    council_slug: slug,
    applications: Array.from(byRef.values()),
    scraped_count: byRef.size,
    total_reported: tot,
    node_version: 'v5-budget',
  };
}

// Hard time budget: n8n aborts the task at 300s. We stop starting new work well
// before that so the node always returns cleanly with whatever it managed to scrape,
// rather than being killed (which loses everything and emails nobody).
DEADLINE = Date.now() + 220000;

const out = [];
for (const item of $input.all()) {
  if (Date.now() > DEADLINE) {
    out.push({ json: { council_slug: item.json.council_slug, applications: [], scraped_count: 0, node_version: 'v5-budget', skipped: 'time budget reached before this council' } });
    continue;
  }
  try {
    out.push({ json: await scrapeCouncil(item.json, DEADLINE) });
  } catch (e) {
    // surface the real failure instead of a bare 500, so it can be read in the node output
    out.push({ json: {
      council_slug: item.json.council_slug,
      applications: [],
      scraped_count: 0,
      node_version: 'v5-budget',
      error_detail: String(e && e.message || e),
    }});
  }
}
return out;

// ===== Fetch: Servlet (lenient HTTP) =====
// Replaces the HTTP Request node for the old Idox *servlet* portals (e.g. Staffs Moorlands).
// Those run an old Java server whose responses break Node's strict/undici parser
// ("Invalid character in chunk size"). We fetch with the legacy http(s) module and
// insecureHTTPParser:true (same leniency as curl), then hand the HTML to the existing
// "Parse: Servlet HTML" node via json.data.
// Requires env: NODE_FUNCTION_ALLOW_BUILTIN=http,https

const http = require('http');
const https = require('https');

function fetchLenient(targetUrl, body) {
  return new Promise((resolve, reject) => {
    const u = new URL(targetUrl);
    const lib = u.protocol === 'https:' ? https : http;
    const req = lib.request({
      hostname: u.hostname,
      port: u.port || (u.protocol === 'https:' ? 443 : 80),
      path: u.pathname + u.search,
      method: 'POST',
      insecureHTTPParser: true,
      timeout: 60000,
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
        'Content-Length': Buffer.byteLength(body),
        'User-Agent': 'Mozilla/5.0',
      },
    }, (res) => {
      let d = '';
      res.setEncoding('utf8');
      res.on('data', (c) => { d += c; });
      res.on('end', () => resolve(d));
    });
    req.on('error', reject);
    req.on('timeout', () => { req.destroy(new Error('timeout')); });
    req.end(body);
  });
}

const out = [];
for (const item of $input.all()) {
  const ctx = item.json;
  const body = new URLSearchParams({
    ReceivedDateFrom: ctx.date_from,
    ReceivedDateTo: ctx.date_to,
    Submit: 'Search',
  }).toString();
  const data = await fetchLenient(ctx.portal_url, body);
  out.push({ json: Object.assign({}, ctx, { data }) });
}
return out;
